// E-Commerce Template Extension
'use strict';

(async () => {
  // Add products collection
  await nuvra.data.addCollection({
    name: 'products',
    fields: [
      { name: 'name',        type: 'text',    required: true },
      { name: 'description', type: 'text',    required: false },
      { name: 'price',       type: 'number',  required: true },
      { name: 'image_url',   type: 'text',    required: false },
      { name: 'stock',       type: 'number',  default: 0 },
      { name: 'category',    type: 'text',    required: false },
    ]
  }).catch(() => {});

  // Add orders collection
  await nuvra.data.addCollection({
    name: 'orders',
    fields: [
      { name: 'customer_email', type: 'text',   required: true },
      { name: 'total',          type: 'number', required: true },
      { name: 'status',         type: 'text',   default: 'pending' },
      { name: 'items',          type: 'text',   required: false },
    ]
  }).catch(() => {});

  // Add product card block
  await nuvra.editor.addBlock({
    id:       'product-card',
    label:    'Product Card',
    category: 'E-Commerce',
    content:  `<div style="border:1px solid #f0f0f0;border-radius:12px;overflow:hidden;max-width:280px;">
  <div style="background:#f5f5f5;height:200px;display:flex;align-items:center;justify-content:center;font-size:48px;">🛍️</div>
  <div style="padding:16px;">
    <h3 style="margin:0 0 6px;font-size:16px;">Product Name</h3>
    <p style="color:#888;margin:0 0 12px;font-size:13px;">Short description here</p>
    <div style="display:flex;align-items:center;justify-content:space-between;">
      <span style="font-size:20px;font-weight:700;">$29.99</span>
      <button style="background:#7c6af7;color:#fff;border:none;padding:8px 16px;border-radius:8px;cursor:pointer;">Add to Cart</button>
    </div>
  </div>
</div>`
  });

  console.log('[E-Commerce Template] Initialized successfully');
})();

