// SaaS AI Pack
'use strict';

(async () => {
  // Register the SaaS planner
  await nuvra.ai.registerPlanner({
    name:        'SaaS Planner',
    description: 'Expert SaaS application generator with subscription, dashboard, and onboarding patterns',
    mode:        'app',
    keywords:    ['saas', 'subscription', 'dashboard', 'admin', 'analytics', 'mrr', 'arr', 'churn', 'onboarding', 'b2b'],
    systemPrompt: `You are an expert SaaS application architect. When generating SaaS applications:
- Always include a subscription management page with tier comparison
- Include an analytics dashboard with MRR, ARR, churn rate, and active users metrics
- Add an onboarding flow with progress steps
- Include a settings page with billing, profile, and team management
- Use a professional dark sidebar navigation pattern
- Ensure all data collections include created_at and updated_at timestamps
- Add role-based access patterns (admin, member, viewer)
- Include empty states for all data tables
- Add loading skeletons for async content`
  });

  // Extend prompts with SaaS context
  nuvra.ai.extendPrompt(function(prompt, context) {
    const saasKeywords = ['saas', 'subscription', 'dashboard', 'admin', 'analytics'];
    const isSaas = saasKeywords.some(kw => prompt.toLowerCase().includes(kw));
    if (!isSaas) return prompt;
    return prompt + '\n\n[SaaS AI Pack active: Apply SaaS best practices including subscription management, analytics dashboards, and professional B2B UI patterns.]';
  });

  console.log('[SaaS AI Pack] Registered. AI will now use SaaS-optimised generation strategies.');
})();

